function main(i) {
  const items = i.items || [];
  const targets = [];
  for (const it of items) {
    const d = it.data || {};
    if (d.qty == null || d.reorder_point == null) continue;
    if (Number(d.qty) < Number(d.reorder_point)) {
      targets.push({ code: String(d.code), name: String(d.name ?? ''), order_qty: Number(d.reorder_qty ?? 0) });
    }
  }
  const esc = (v) => { const s = String(v ?? ''); return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const lines = ['品番,品名,発注数'].concat(targets.map(t => [t.code, t.name, t.order_qty].map(esc).join(',')));
  return { targets, csv: lines.join('\r\n') + '\r\n', count: targets.length };
}

function main(i) { const lines = i.items.map((r) => `${r.data.faq_no}｜質問: ${r.data.question}｜回答: ${r.data.answer}`); return { text: `以下はよくある質問（FAQ）の一覧です。
