function norm(s){return String(s||'').normalize('NFKC').toLowerCase().replace(/[\s\u3000、。,.!！?？「」『』()（）\[\]【】:：;；・\-ー~〜]/g,'');}
function bigrams(s){const m=new Map();for(let k=0;k<s.length-1;k++){const g=s.slice(k,k+2);m.set(g,(m.get(g)||0)+1);}return m;}
function dice(a,b){const A=bigrams(a),B=bigrams(b);let na=0,nb=0,inter=0;for(const v of A.values())na+=v;for(const v of B.values())nb+=v;if(na+nb===0)return 0;for(const [g,c] of A){inter+=Math.min(c,B.get(g)||0);}return 2*inter/(na+nb);}
function main(i){const q=norm(i.question);let best=null;for(const it of (i.items||[])){const d=it.data||{};const fq=norm(d.question);if(!fq)continue;let s=dice(q,fq);if(fq.length>=4&&q.includes(fq))s=Math.max(s,0.9);if(!best||s>best.score)best={score:s,faq_no:d.faq_no,question:d.question,answer:d.answer};}if(best&&best.score>=0.5)return {matched:true,score:best.score,faq_no:String(best.faq_no??''),faq_question:String(best.question??''),answer:String(best.answer??'')};return {matched:false,score:best?best.score:0,faq_no:'',faq_question:'',answer:''};}

